import {buildCatalog,groups} from './catalog.mjs';
import {valueOf} from './lessons.mjs';
import {allChanges} from './trace.mjs';
import {esc,help,helpTexts,moduleMarkup,worldMarkup} from './course-ui.mjs?v=local-tutor-1';
import {createLocalTutor} from './local-chat.mjs';
export const escapeHTML=esc;
function colorLine(line){const re=/("(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|\b(?:int|char|void|return|while|if|else|const|unsigned|typedef|struct)\b|\b\d+\b|\b(?:printf|putchar|write|malloc|free|solve|visit|ft_\w+)\b)/g;let out='',last=0;for(const m of line.matchAll(re)){out+=esc(line.slice(last,m.index));const k=/^["']/.test(m[0])?'string':/^\d/.test(m[0])?'num':/^(printf|putchar|write|malloc|free|solve|visit|ft_)/.test(m[0])?'function':'key';out+=`<span class="tok-${k}">${esc(m[0])}</span>`;last=m.index+m[0].length;}return out+esc(line.slice(last));}
export async function mountApp(doc=globalThis.document,win=globalThis.window,providedModules){
 const $=id=>doc.getElementById(id),modules=providedModules||await (await fetch(new URL('./curriculum.json',import.meta.url))).json(),catalog=buildCatalog();
 let module=null,exercise=null,simulation=null,index=0,timer=null,selected=null,activeHelp=null,pinned=false;
 let notes={},oldNotes={};const completed=new Set();
 try{const p=JSON.parse(win.localStorage.getItem('learninglab-progress')||'[]');if(Array.isArray(p))p.forEach(k=>completed.add(k));}catch{}
 try{notes=JSON.parse(win.localStorage.getItem('learninglab-notes')||'{}')||{};if(typeof notes!=='object'||Array.isArray(notes))notes={};oldNotes=JSON.parse(win.localStorage.getItem('pointerlab-notes')||'{}')||{};}catch{}
 const localTutor=createLocalTutor({doc,win,getLesson:()=>win.LearningLab,pause:stop});
 const noteKey=()=>module.slug+'/'+exercise.id;
 const currentFrame=()=>simulation.steps[index];
 const previousFrame=()=>simulation.steps[Math.max(0,index-1)];
 const atEnd=()=>index===simulation.steps.length-1;
 function stop(){if(timer!==null)win.clearInterval(timer);timer=null;if($('play')){$('play').innerHTML='▷ Play';$('play').setAttribute('aria-pressed','false');$('play').setAttribute('aria-label','Play automatic steps');}}
 function hideHelp(){if(activeHelp)activeHelp.setAttribute('aria-expanded','false');activeHelp=null;pinned=false;$('contextTip').hidden=true;}
 function showHelp(button,pin=false){if(activeHelp&&activeHelp!==button)activeHelp.setAttribute('aria-expanded','false');activeHelp=button;pinned=pin;const tip=$('contextTip');tip.textContent=helpTexts[button.dataset.help]||'Inspect this section alongside the current operation.';tip.hidden=false;button.setAttribute('aria-expanded','true');const r=button.getBoundingClientRect?.()||{left:20,bottom:50,top:30};const width=Math.min(280,(win.innerWidth||1000)-24),left=Math.max(12,Math.min(r.left,(win.innerWidth||1000)-width-12));tip.style.width=width+'px';tip.style.left=left+'px';tip.style.top=Math.max(12,r.bottom+8)+'px';if(tip.getBoundingClientRect&&tip.getBoundingClientRect().bottom>(win.innerHeight||1000)-12)tip.style.top=Math.max(12,r.top-tip.getBoundingClientRect().height-8)+'px';}
 function drawNav(){const q=$('search').value.trim().toLowerCase();$('lessons').innerHTML=groups.map(([id,title])=>{const relevant=modules.filter(m=>m.group===id&&(!q||(`${m.title} ${m.slug} ${m.exercises.map(e=>e.title+' '+e.concepts.join(' ')).join(' ')}`).toLowerCase().includes(q)));if(!relevant.length)return '';return `<details class="module-group" ${q||!module||module.group===id?'open':''}><summary>${esc(title)}<span>${relevant.length}</span></summary>${relevant.map(m=>`<button class="module-item" data-module="${m.slug}" ${module?.slug===m.slug?'aria-current="page"':''}><span class="module-index">${m.slug.slice(0,2)}</span><span>${esc(m.title)}<small>${esc(m.slug)}</small></span><span class="module-done">${m.exercises.every(e=>completed.has(m.slug+'/'+e.id))?'✓':''}</span></button>`).join('')}</details>`;}).join('')||'<p class="search-empty">No matching module or exercise.</p>';$('courseCount').textContent=`${completed.size} of ${modules.reduce((n,m)=>n+m.exercises.length,0)} entries explored`;}
 function home(){stop();hideHelp();module=null;exercise=null;simulation=null;drawNav();$('content').innerHTML=`<section class="home-hero"><span class="eyebrow">YOUR SCHOOL MODULES, CONNECTED</span><h1>Small steps.<br><span>Solid foundations.</span> ${help('map','Learning map')}</h1><p>Understand what each exercise teaches. Follow values, addresses, calls, files, and output one operation at a time.</p><div class="home-stats"><span><strong>${modules.length}</strong> source modules &amp; Rushes</span><span><strong>${modules.reduce((n,m)=>n+m.exercises.length,0)}</strong> learning entries</span><span><strong>${catalog.length}</strong> concept demonstrations</span></div></section><section class="learning-path"><h2>Your module map ${help('map','Module map')}</h2><p>Follow the school’s order, or return to a concept when a later module depends on it.</p><div class="module-map">${groups.map(([id,title],i)=>`<section class="map-group"><div class="map-number">${id==='rushes'?'R':String(i).padStart(2,'0')}</div><div><h3>${esc(title.replace(/^\d+ · /,''))}</h3>${modules.filter(m=>m.group===id).map(m=>`<button data-module="${m.slug}" class="map-module"><span>${esc(m.title)}</span><small>${m.exercises.length} entries →</small></button>`).join('')}</div></section>`).join('')}</div></section><section class="study-method"><h2>Make every step count ${help('observe','Study method')}</h2><div><p><strong>1. Predict</strong>Read the goal and code line. Say what you think will change.</p><p><strong>2. Observe</strong>Execute one operation. Follow the highlighted cells or workspace objects.</p><p><strong>3. Explain</strong>Compare before and after. Describe the copied value or followed address in your own words.</p></div><p class="model-note">Concept demonstrations isolate mechanisms and are not submission files. Source links keep exact assignment rules within reach. Addresses, descriptor numbers, and example Git IDs are illustrative.</p></section>`;expose();}
 function selectModule(slug,exerciseId,simId,{route=true}={}){const m=modules.find(m=>m.slug===slug);if(!m)return;stop();hideHelp();module=m;exercise=m.exercises.find(e=>e.id===exerciseId)||m.exercises[0];simulation=catalog.find(s=>s.id===simId&&exercise.simulations.includes(simId))||catalog.find(s=>s.id===exercise.simulations[0]);if(!simulation)throw Error('Missing simulation for '+noteKey());index=0;selected=null;$('content').innerHTML=moduleMarkup(module,exercise,catalog);bindControls();$('simulationSelect').value=simulation.id;$('notes').value=typeof notes[noteKey()]==='string'?notes[noteKey()]:typeof oldNotes[simulation.id]==='string'?oldNotes[simulation.id]:'';drawNav();render();if(route)win.history?.replaceState?.(null,'',`#module=${module.slug}&exercise=${exercise.id}&sim=${simulation.id}`);}
 function bindControls(){
  $('exerciseSelect').addEventListener('change',()=>selectModule(module.slug,$('exerciseSelect').value));
  $('simulationSelect').addEventListener('change',()=>{stop();simulation=catalog.find(s=>s.id===$('simulationSelect').value);index=0;selected=null;$('code').scrollTop=0;render();win.history?.replaceState?.(null,'',`#module=${module.slug}&exercise=${exercise.id}&sim=${simulation.id}`);});
  $('prev').addEventListener('click',()=>move(-1));$('next').addEventListener('click',()=>move(1));
  $('reset').addEventListener('click',()=>{stop();index=0;selected=null;$('code').scrollTop=0;render();});
  $('timeline').addEventListener('input',()=>{stop();index=Math.max(0,Math.min(simulation.steps.length-1,Math.round(Number($('timeline').value)||0)));render();});
  $('play').addEventListener('click',()=>timer===null?start():stop());$('speed').addEventListener('change',()=>{if(timer!==null){stop();start();}});
  $('memory').addEventListener('click',e=>{const button=e.target.closest('[data-cell]');if(button){selected=button.dataset.cell;drawMemory(currentFrame(),index?allChanges(previousFrame(),currentFrame()):[]);}});
  $('notes').addEventListener('input',()=>{notes[noteKey()]=$('notes').value;try{win.localStorage.setItem('learninglab-notes',JSON.stringify(notes));$('notesStatus').textContent='Saved in this browser';}catch{$('notesStatus').textContent='Local saving is unavailable';}});
 }
 function move(delta){if(!simulation)return;stop();index=Math.max(0,Math.min(simulation.steps.length-1,index+delta));render();}
 function start(){if(!simulation||atEnd())return;$('play').innerHTML='Ⅱ Pause';$('play').setAttribute('aria-pressed','true');$('play').setAttribute('aria-label','Pause automatic steps');timer=win.setInterval(()=>{index=Math.min(simulation.steps.length-1,index+1);render();if(atEnd())stop();},Number($('speed').value)||4000);}
 function drawInspector(frame){const c=frame.cells[selected];if(!c){$('inspector').innerHTML='<span class="inspector-icon">⌖</span><p>Choose an object to compare its own address, stored value, and target.</p>';return;}let text=`<strong>${esc(c.name)}</strong> lives at <strong>${c.address}</strong> and stores <strong>${esc(valueOf(c))}</strong>.`;if(c.target){const t=frame.cells[c.target];text+=` Following its address reaches <strong>${esc(t.name)}</strong> at ${t.address}, which stores <strong>${esc(valueOf(t))}</strong>.`;}else if(c.invalid)text+=' Its stored address has expired. Do not dereference it.';else if(c.type.includes('*'))text+=c.value==='NULL'?' NULL points to no object.':' There is no initialized target to follow.';else text+=` Its address and its stored value are different things.`;$('inspector').innerHTML=`<span class="inspector-icon">⌖</span><p>${text}</p>`;}
 function drawMemory(frame,diff){const written=new Set(diff.filter(c=>c.kind!=='removed').map(c=>c.id)),cells=Object.values(frame.cells);if(!frame.cells[selected])selected=null;$('world').innerHTML=worldMarkup(frame.world);$('world').hidden=!frame.world;$('world').className='world '+(written.has('world')?'world-changed':'');$('memory').innerHTML=cells.length?[...new Set(cells.map(c=>c.scope))].map(scope=>`<div class="scope-heading"><span>${esc(scope)}</span><span>${cells.filter(c=>c.scope===scope).length} OBJECTS</span></div>`+cells.filter(c=>c.scope===scope).map(c=>`<button class="cell ${written.has(c.id)?'written':frame.reads.includes(c.id)?'read':''} ${selected===c.id?'selected':''}" data-cell="${c.id}" aria-label="${esc(c.name)}, ${esc(c.type)}, address ${c.address}, stores ${esc(valueOf(c))}" aria-pressed="${selected===c.id}"><span class="cell-name">${esc(c.name)}<span class="cell-type">${esc(c.type)}</span></span><span class="cell-address">${c.address}</span><span class="cell-value ${c.value===undefined?'empty':''}">${esc(valueOf(c))}</span><span class="cell-target">${c.invalid?'expired':c.target?'→ '+esc(frame.cells[c.target].name):''}</span></button>`).join('')).join(''):`<div class="empty-memory"><strong>{ }</strong><span>${simulation.kind==='c'?'No variables created yet.':'No C memory objects in this command step.'}</span></div>`;const ptrs=cells.filter(c=>c.target);$('graph').innerHTML=ptrs.length?ptrs.map(p=>{const t=frame.cells[p.target];return `<div class="connection"><div class="node ${frame.focus.includes(p.id)?'focus':''}">${esc(p.name)}<small>stores ${p.value}</small></div><span class="connection-arrow">→</span><div class="node ${frame.focus.includes(t.id)?'focus':''}">${esc(t.name)} = ${esc(valueOf(t))}<small>at ${t.address}</small></div></div>`;}).join(''):'<p class="connection-empty">No initialized address connection at this step.</p>';$('calls').innerHTML=(frame.calls||[]).length?frame.calls.map((c,i)=>`<span class="call-chip ${i===frame.calls.length-1?'active':''}">${esc(c)}<small>${i===frame.calls.length-1?'active':'waiting'}</small></span>`).join(''):'<span class="connection-empty">No runtime C call is active.</span>';drawInspector(frame);}
 function render(){if(!simulation)return;const frame=currentFrame(),before=previousFrame(),diff=index?allChanges(before,frame):[],outputChanged=before.output!==frame.output;
  if(atEnd()){completed.add(noteKey());try{win.localStorage.setItem('learninglab-progress',JSON.stringify([...completed]));}catch{}stop();drawNav();}
  $('simulationIntro').innerHTML=`<span class="simulation-kind">${simulation.kind==='c'?'C CONCEPT EXAMPLE':'COMMAND / WORKFLOW MODEL'}</span><strong>${esc(simulation.title)}</strong><p>${esc(simulation.summary)}</p>`;
  $('stepLabel').textContent=index?`Step ${index} / ${simulation.steps.length-1}`:'Ready to run';$('operationCount').textContent=`${simulation.steps.length-1} operations`;$('timeline').max=simulation.steps.length-1;$('timeline').value=index;$('timeline').setAttribute('aria-valuetext',index?`Step ${index}: ${frame.title}`:'Ready to run');$('prev').disabled=index===0;$('next').disabled=atEnd();$('play').disabled=atEnd();
  $('fileName').textContent=simulation.id+(simulation.kind==='c'?'.c':'.sh');$('sourceKind').textContent=simulation.kind==='c'?'Complete runnable C':'Illustrative command sequence';$('scopeLabel').textContent=frame.scope;
  const code=$('code'),oldScroll=code.scrollTop||0;code.innerHTML=simulation.code.map((l,i)=>`<div class="code-line ${frame.line===i+1?'active':''}" ${frame.line===i+1?'aria-current="step"':''}><span class="line-num">${i+1}</span><span class="line-text">${colorLine(l)||' '}</span></div>`).join('');code.scrollTop=oldScroll;const active=code.querySelector('.active');if(active&&(active.offsetTop<code.scrollTop||active.offsetTop+active.offsetHeight>code.scrollTop+code.clientHeight))code.scrollTop=Math.max(0,active.offsetTop-code.clientHeight/2);
  $('lineLabel').textContent=frame.line?`Line ${frame.line} · ${frame.scope}${atEnd()?' · finished':''}`:'Ready at the example’s starting state';$('coachStep').textContent=index===0?'BEFORE THE FIRST OPERATION':atEnd()?'EXAMPLE COMPLETE':`OPERATION ${String(index).padStart(2,'0')}`;$('stepTitle').textContent=frame.title;$('what').textContent=frame.what;$('observe').textContent=frame.observe;$('flow').textContent=frame.flow;$('eventBadge').textContent=atEnd()?'DONE':index===0?'READY':outputChanged?'OUTPUT':diff.length?'STATE':'READ / CHECK';$('eventBadge').className='event-badge '+(diff.length||outputChanged?'changed':'');$('changeCount').textContent=diff.length?`${diff.length} change${diff.length===1?'':'s'}`:outputChanged?'output only':'no stored change';$('changes').innerHTML=diff.map(c=>`<div class="change-row"><div class="change-name">${esc(c.name)}<span class="change-kind">${c.kind==='written'?'changed':c.kind==='created'?'created':'left scope'}</span></div><div class="change-values"><span class="old-value">${esc(c.before)}</span><span class="change-arrow">→</span><span class="new-value">${esc(c.after)}</span></div></div>`).join('');if(outputChanged)$('changes').innerHTML+=`<div class="change-row terminal-change"><div class="change-name">terminal<span class="change-kind">appended</span></div><div class="change-values"><span class="old-value">${before.output?'existing output':'empty'}</span><span class="change-arrow">→</span><span class="new-value">+ ${esc(frame.output.slice(before.output.length).replace(/\n/g,' ↵\n'))}</span></div></div>`;if(!diff.length&&!outputChanged)$('changes').innerHTML='<div class="no-change">Stored state and terminal output stay unchanged.</div>';drawMemory(frame,diff);$('terminal').textContent=frame.output;$('terminalEmpty').hidden=!!frame.output;$('terminalStatus').textContent=outputChanged?'OUTPUT ADDED THIS STEP':frame.output?'CURRENT OUTPUT':'WAITING FOR OUTPUT';$('terminalPrompt').textContent=simulation.kind==='c'?`$ ./example ${(simulation.args||[]).join(' ')}`:'$ illustrative workspace';expose();
 }
 function expose(){win.LearningLab={modules,catalog,get module(){return module;},get exercise(){return exercise;},get simulation(){return simulation;},get index(){return index;},get frame(){return simulation?currentFrame():null;},get before(){return simulation?previousFrame():null;},get diff(){return simulation&&index?allChanges(previousFrame(),currentFrame()):[];},selectModule,render,stop,home};localTutor.sync();}
 function route(){const hash=win.location?.hash||'';if(hash.startsWith('#module=')){const params=new URLSearchParams(hash.slice(1));selectModule(params.get('module'),params.get('exercise'),params.get('sim'),{route:false});}else home();}
 $('lessons').addEventListener('click',e=>{const b=e.target.closest('[data-module]');if(b)selectModule(b.dataset.module);});$('content').addEventListener('click',e=>{const m=e.target.closest('[data-module]'),x=e.target.closest('[data-exercise]');if(m)selectModule(m.dataset.module);else if(x)selectModule(module.slug,x.dataset.exercise);});$('search').addEventListener('input',drawNav);$('homeButton').addEventListener('click',()=>{win.history?.replaceState?.(null,'','#home');home();});$('helpButton').addEventListener('click',()=>{$('guide').hidden=!$('guide').hidden;$('helpButton').setAttribute('aria-expanded',String(!$('guide').hidden));});
 doc.addEventListener('pointerover',e=>{const b=e.target.closest?.('[data-help]');if(b&&!pinned)showHelp(b);});doc.addEventListener('pointerout',e=>{const b=e.target.closest?.('[data-help]');if(b&&activeHelp===b&&!pinned&&doc.activeElement!==b&&e.relatedTarget?.closest?.('[data-help]')!==b)hideHelp();});doc.addEventListener('focusin',e=>{const b=e.target.closest?.('[data-help]');if(b)showHelp(b);});doc.addEventListener('focusout',e=>{if(e.target===activeHelp&&!pinned)hideHelp();});doc.addEventListener('click',e=>{const b=e.target.closest?.('[data-help]');if(b){e.preventDefault();e.stopPropagation();if(activeHelp===b&&pinned)hideHelp();else showHelp(b,true);}else if(e.target!==$('contextTip'))hideHelp();});
 doc.addEventListener('keydown',e=>{if(e.key==='Escape'){hideHelp();return;}if(e.ctrlKey||e.altKey||e.metaKey||['INPUT','SELECT','TEXTAREA','BUTTON','SUMMARY','A'].includes(e.target.tagName)||e.target.isContentEditable)return;if(e.key==='ArrowRight'){e.preventDefault();move(1);}else if(e.key==='ArrowLeft'){e.preventDefault();move(-1);}else if(e.key.toLowerCase()==='r'&&simulation){e.preventDefault();$('reset').click();}else if(e.code==='Space'&&simulation){e.preventDefault();timer===null?start():stop();}});doc.addEventListener('visibilitychange',()=>{if(doc.hidden){stop();hideHelp();}});win.addEventListener('pagehide',stop);win.addEventListener('resize',hideHelp);doc.addEventListener('scroll',hideHelp,true);win.addEventListener('hashchange',route);route();return win.LearningLab;
}
if(typeof document!=='undefined'&&typeof window!=='undefined')mountApp().catch(error=>{document.getElementById('content').innerHTML='<p class="load-error">The learning content could not load. Reload this page to try again.</p>';console.error(error);});
